    /* ---------- typical mistakes ---------- */
    fixes: [
      { bad: 'Ich bin Diätassistentin seit drei Jahren.', good: 'Ich arbeite seit drei Jahren als Diätassistentin.', why: 'Time comes before the job: “seit drei Jahren”. With “arbeiten” you need “als”.' },
      { bad: 'Der Patient hat Allergie auf Nüsse.', good: 'Der Patient ist allergisch gegen Nüsse.', why: '“allergisch gegen” or “eine Allergie gegen …” – never “auf”, and “Allergie” needs “eine”.' },
      { bad: 'Sie dürfen keinen Zucker essen.', good: 'Versuchen Sie, möglichst wenig Zucker zu essen.', why: 'In counselling “nicht dürfen” sounds like a ban. Soft suggestions motivate more – and are usually more correct.' },
      { bad: 'Wie viel Kilo Sie wiegen?', good: 'Wie viel wiegen Sie?', why: 'In a W-question the verb comes straight after the question word.' },
      { bad: 'Ich habe gestern gemacht die Kontrolle.', good: 'Ich habe die Kontrolle gestern gemacht.', why: 'Perfect tense: the participle (gemacht) goes to the very end.' },
      { bad: 'Er bekommt kein Fleisch, weil er ist Vegetarier.', good: 'Er bekommt kein Fleisch, weil er Vegetarier ist.', why: 'After “weil” the conjugated verb goes to the end.' },
      { bad: 'Ich rufe an wegen der Patient in Zimmer 7.', good: 'Ich rufe wegen des Patienten in Zimmer 7 an.', why: '“anrufen” is separable (an at the end). “wegen” + genitive: des Patienten (in speech also “wegen dem Patienten”).' },
      { bad: 'Die Temperatur ist 5 Grade.', good: 'Die Temperatur liegt bei 5 Grad.', why: '“Grad” has no plural ending after numbers. “liegt bei” sounds professional.' },
      { bad: 'Kannst du mir helfen mit den Tabletts?', good: 'Kannst du mir mit den Tabletts helfen?', why: 'With a modal verb the infinitive (helfen) goes to the end.' },
      { bad: 'Hast du Schmerzen beim Schlucken?', good: 'Haben Sie Schmerzen beim Schlucken?', why: 'Adult patients get “Sie” – unless they offer you “du”.' },
      { bad: 'Ich muss die Liste kontrolliert.', good: 'Ich muss die Liste kontrollieren.', why: 'Modal verb + infinitive, not the participle.' },
      { bad: 'Die Kühlschrank ist kaputt.', good: 'Der Kühlschrank ist kaputt.', why: 'der Schrank → der Kühlschrank. The last part of a compound decides the article.' },
      { bad: 'Ich bin fertig mit die Bandabnahme.', good: 'Ich bin mit der Bandabnahme fertig.', why: '“mit” always takes the dative: mit der Bandabnahme.' },
      { bad: 'Sie hat abgenommen sechs Kilo in drei Monaten.', good: 'Sie hat in drei Monaten sechs Kilo abgenommen.', why: 'The participle “abgenommen” goes to the end of the sentence.' },
      { bad: 'Ich freue mich für die Hospitation.', good: 'Ich freue mich auf die Hospitation.', why: '“sich freuen auf” = looking forward to (future). “sich freuen über” = happy about (now / past).' },
      { bad: 'Ich habe angefangen hier im Oktober.', good: 'Ich habe im Oktober hier angefangen.', why: 'Time – place – participle at the end: im Oktober hier angefangen.' },
      { bad: 'Bitte macht die Portion für Zimmer 3 püriert.', good: 'Bitte püriert die Portion für Zimmer 3.', why: 'Use the exact verb: pürieren. In the kitchen team the plural “ihr” form: püriert!' },
      { bad: 'Das Essen ist zu viel salzig.', good: 'Das Essen ist viel zu salzig.', why: '“viel zu” + adjective = much too … (word order!).' },
    ],

